def is_equal_to_sum_even(n):
    """Determines if a number can be expressed as the sum of four positive even numbers.
    Returns True if n is an even integer >= 8, False otherwise."""
    if not isinstance(n, int):
        return False
    if n < 8 or n % 2 != 0:
        return False
    return True

